tinyMCE.PluginManager.add("stylebuttons",function(e,t){["h1","h2","h3","h4","h5","h6"].forEach(function(o){e.addButton("style-"+o,{tooltip:"Toggle "+o,text:o.toUpperCase(),onClick:function(){e.execCommand("mceToggleFormat",!1,o)},onPostRender:function(){var n=this,t=function(){e.formatter.formatChanged(o,function(t){n.active(t)})};e.formatter?t():e.on("init",t)}})})});
